async (page) => {
  const urls = ['http://127.0.0.1:9101/people','http://127.0.0.1:9101/staff','http://127.0.0.1:9102/spa','http://127.0.0.1:9103/Residents.aspx','http://127.0.0.1:9104/Residents.aspx'];
  const ctx = page.context();
  const res = await Promise.all(urls.map(async u => {
    const p = await ctx.newPage();
    try {
      await p.goto(u, {waitUntil:'networkidle'});
      await p.waitForTimeout(800);
      const html = await p.content();
      const text = await p.evaluate(() => document.body.innerText);
      return {u, title: await p.title(), url: p.url(), text: text.slice(0,2500), htmlLen: html.length, html: html.slice(0,3000)};
    } catch(e) { return {u, err: String(e)}; } finally { await p.close(); }
  }));
  return JSON.stringify(res, null, 1);
}

